-- Reference catalog snapshot and source-backed corrections, reviewed 2026-10-03.
-- Only reference rows: no users, sessions, history or credentials are included.
-- Resolve every relationship by slug; existing IDs and created_at values survive upserts.
-- See docs/data/exercise-catalog-audit.md for evidence, limitations and restore checks.
-- Requires a transaction (Supabase migrations do this; manual runs use psql --single-transaction).
begin;
-- Imported explicit IDs left serial counters at 1. Repair BEFORE any default-ID insert.
-- Never move a sequence backwards; nextval/setval are not transactional in PostgreSQL.
select setval(pg_get_serial_sequence('public.exercises','id'), greatest((select coalesce(max(id),1) from public.exercises),(select last_value from public.exercises_id_seq)), true);
select setval(pg_get_serial_sequence('public.muscle_groups','id'), greatest((select coalesce(max(id),1) from public.muscle_groups),(select last_value from public.muscle_groups_id_seq)), true);
select setval(pg_get_serial_sequence('public.programs','id'), greatest((select coalesce(max(id),1) from public.programs),(select last_value from public.programs_id_seq)), true);
select setval(pg_get_serial_sequence('public.program_days','id'), greatest((select coalesce(max(id),1) from public.program_days),(select last_value from public.program_days_id_seq)), true);
select setval(pg_get_serial_sequence('public.program_slots','id'), greatest((select coalesce(max(id),1) from public.program_slots),(select last_value from public.program_slots_id_seq)), true);
create temporary table catalog_muscles (slug text primary key, name text not null) on commit drop;
select slug,name from catalog_muscles order by slug
on conflict (slug) do nothing;

create temporary table catalog_entries (entry jsonb not null) on commit drop;

-- Convert portable contraindication targets into local IDs; retain slugs for auditability.
update catalog_entries c set entry = jsonb_set(entry, '{contraindications}', coalesce((
  select jsonb_agg(case when rule #> '{target,muscle_group_slugs}' is not null then
    jsonb_set(rule, '{target,muscle_group_ids}', (
      select coalesce(jsonb_agg(m.id order by s.ordinality), '[]'::jsonb)
      from jsonb_array_elements_text(rule #> '{target,muscle_group_slugs}') with ordinality s(slug,ordinality)
      join public.muscle_groups m on m.slug=s.slug
    )) else rule end order by ordinality)
  from jsonb_array_elements(entry->'contraindications') with ordinality r(rule,ordinality)
), '[]'::jsonb));

 slug,name,movement_pattern,equipment,is_bodyweight,aliases,tags,media,contraindications,is_active,
 category,tracking_mode,instructions,source_urls,review_status,catalog_notes
)
select entry->>'slug',entry->>'name',entry->>'movement_pattern',entry->'equipment',
 (entry->>'is_bodyweight')::boolean,entry->'aliases',entry->'tags',entry->'media',entry->'contraindications',
 (entry->>'is_active')::boolean,entry->>'category',entry->>'tracking_mode',entry->'instructions',
 entry->'source_urls',entry->>'review_status',entry->>'catalog_notes'
from catalog_entries
on conflict (slug) do update set
 name=excluded.name, movement_pattern=excluded.movement_pattern, equipment=excluded.equipment,
 is_bodyweight=excluded.is_bodyweight, aliases=excluded.aliases, tags=excluded.tags, media=excluded.media,
 contraindications=excluded.contraindications, is_active=excluded.is_active, category=excluded.category,
 tracking_mode=excluded.tracking_mode, instructions=excluded.instructions, source_urls=excluded.source_urls,
 review_status=excluded.review_status, catalog_notes=excluded.catalog_notes;

-- Replace only this catalog's mappings, leaving custom exercise rows untouched.
delete from public.exercise_muscle_map em using public.exercises e, catalog_entries c
where em.exercise_id=e.id and e.slug=c.entry->>'slug';
select e.id,m.id,detail->>'role',(detail->>'contribution')::numeric
from catalog_entries c
join public.exercises e on e.slug=c.entry->>'slug'
cross join lateral jsonb_array_elements(c.entry->'muscles') detail
join public.muscle_groups m on m.slug=detail->>'muscle';

-- Keep locked template movement metadata aligned after catalog corrections.
update public.program_slots ps set movement_pattern=e.movement_pattern
from public.exercises e join catalog_entries c on e.slug=c.entry->>'slug'
where ps.locked_exercise_id=e.id and ps.movement_pattern is distinct from e.movement_pattern;

-- Constraints staged by the schema migration are validated after legacy repairs.
-- Imported flex slots identify their source exercise inside prescription JSON.
-- Correct copied selection metadata, preserving all authored sets/reps/RIR and source notes.
with slot_corrections as (
select distinct on (ps.id) ps.id, e.id as exercise_id
from public.program_slots ps cross join public.exercises e
where e.slug in ('arnold_press','back_squat','banded_internal_rotation_stretch','bar_curl','barbell_row','battle_ropes','beltless_paused_deadlift_below_knee','bulgarian_split_squat','cable_flye','cable_upright_row','comp_bench_press','comp_deadlift','comp_squat','conventional_deadlift','db_bench_press','db_flye','db_romanian_deadlift','dead_bug','elliptical','glute_ham_raise','goblet_kb_front_squat','goblet_squat','hip_thrust','incline_treadmill_walk','jump_rope','kelso_shrug','leg_extension','leg_press','leg_press_calf_raise','lying_leg_curl','machine_lat_pullover','machine_shoulder_press','nordic_ham_curl','pause_squat','pec_deck','plate_loaded_neck_curls','push_up','seated_barbell_shoulder_press','seated_leg_curl','shoulder_dislocations','smith_machine_shoulder_press','stair_climber','standing_db_arnold_press','stationary_bike','sumo_deadlift','t_shirt_pause_bench_press','upright_row')
and ps.lock_type='flex'
and (lower(ps.prescription #>> '{source,canonical_name}')=lower(e.name)
 or exists (select 1 from jsonb_array_elements_text(e.aliases) a(name)
            where lower(a.name)=lower(ps.prescription #>> '{source,canonical_name}')))
-- Exact names win over aliases; slug order makes alias-only ties deterministic.
order by ps.id, (lower(ps.prescription #>> '{source,canonical_name}')=lower(e.name)) desc, e.slug
)
update public.program_slots ps set
 movement_pattern=e.movement_pattern,
 equipment_allowed=e.equipment,
 muscle_targets=(select jsonb_object_agg(m.slug,em.contribution)
   from public.exercise_muscle_map em join public.muscle_groups m on m.id=em.muscle_group_id
   where em.exercise_id=e.id)
from slot_corrections c join public.exercises e on e.id=c.exercise_id
where ps.id=c.id;

alter table public.exercises validate constraint exercises_category_check;
alter table public.exercises validate constraint exercises_tracking_mode_check;
alter table public.exercises validate constraint exercises_instructions_string_array_check;
alter table public.exercises validate constraint exercises_source_urls_string_array_check;
alter table public.exercises validate constraint exercises_review_status_check;
alter table public.exercises validate constraint exercises_equipment_string_array_check;
alter table public.exercises validate constraint exercises_aliases_string_array_check;
alter table public.exercises validate constraint exercises_tags_string_array_check;
alter table public.exercises validate constraint exercises_media_object_check;
alter table public.exercises validate constraint exercises_contraindications_array_check;
alter table public.exercise_muscle_map validate constraint exercise_muscle_map_role_check;
alter table public.exercise_muscle_map validate constraint exercise_muscle_map_contribution_check;
alter table public.programs validate constraint programs_days_per_week_check;
alter table public.programs validate constraint programs_metadata_object_check;
alter table public.program_days validate constraint program_days_day_index_check;
alter table public.program_days validate constraint program_days_theme_tags_string_array_check;
alter table public.program_slots validate constraint program_slots_slot_index_check;
alter table public.program_slots validate constraint program_slots_lock_type_check;
alter table public.program_slots validate constraint program_slots_lock_consistency_check;
alter table public.program_slots validate constraint program_slots_set_range_check;
alter table public.program_slots validate constraint program_slots_rep_range_check;
alter table public.program_slots validate constraint program_slots_rir_range_check;
alter table public.program_slots validate constraint program_slots_equipment_allowed_string_array_check;
alter table public.program_slots validate constraint program_slots_tags_required_string_array_check;
alter table public.program_slots validate constraint program_slots_tags_blocked_string_array_check;
alter table public.program_slots validate constraint program_slots_muscle_targets_object_check;
alter table public.program_slots validate constraint program_slots_prescription_object_check;

commit;
